#!/usr/bin/env python
"""Perbaikan Fase 1: tombol demo di Mulai di Sini dapat dijangkau lagi + tes yang tidak bergantung urutan.

Jalankan dari folder proyek:  .\\.venv\\Scripts\\python.exe patch_fase1.py
Menimpa 2 berkas (sudah diverifikasi checksum). Aman dijalankan ulang.
"""
import base64, hashlib, sys, zlib
from pathlib import Path

PAYLOAD = {
"src/firewall_sim/ui/pages/start_here.py": {
"sha256": "6723deda1cde2f0a47fd3f8508f49db787fc53f9f111ef796e7911e5ee2acee1",
"b64": ""
},
"tests/test_ui.py": {
"sha256": "45cd6e3d27993436f8e0485b0f1ee00d445479c333d46abb9adcd74aec2ba712",
"b64": ""
}
}

def main():
    root = Path.cwd()
    if not (root / "src" / "firewall_sim").exists():
        sys.exit("GAGAL: jalankan dari folder proyek.")
    bad = 0
    for rel, item in PAYLOAD.items():
        data = zlib.decompress(base64.b64decode(item["b64"]))
        dest = root / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(data)
        ok = hashlib.sha256(dest.read_bytes()).hexdigest() == item["sha256"]
        print(("OK     " if ok else "GAGAL  ") + rel)
        bad += 0 if ok else 1
    sys.exit(1 if bad else 0)

if __name__ == "__main__":
    main()